class TestSubprocess(TestCase):
    # [CLASS DOC] Base test case that patches the FX compile mode to subprocess for every test
    # using an exit stack. Resets Dynamo and FxCompile statistics on setup, and on teardown
    # asserts that no in-process compile happened (which would mean the graph failed to
    # serialize). Subclasses below add the device and checker.
    def setUp(self):
        # [FUNCTION DOC] Resets Dynamo and the FxCompile statistics, calls the parent setup, then
        # enters a patch that sets the compile mode to subprocess; the patch is kept on an exit
        # stack stored on the instance.
        torch._dynamo.reset()
        FxCompile._reset_stats()

        super().setUp()

        self._stack = contextlib.ExitStack()
        self._stack.enter_context(
            patch(
                "torch._inductor.compile_fx.fx_compile_mode",
                FxCompileMode.SUBPROCESS,
            )
        )

    def tearDown(self):
        # [FUNCTION DOC] Asserts that the in-process compile statistics recorded zero codegen-and-
        # compile calls, closes the exit stack (undoing the mode patch), runs the base teardown
        # and resets Dynamo. Fails the test if any compile happened in-process.
        # Check that the test didn't instigate an in-process compile - which
        # would mean that something about the fx graph failed to serialize. If
        # some tests are expected to fail then we should probably add a list of
        # expected failures here.
        self.assertEqual(
            FxCompile._compile_stats[type(_InProcessFxCompile)].codegen_and_compile, 0
        )
        self._stack.close()
        TestCase.tearDown(self)
        torch._dynamo.reset()

    @skipIfRocm(msg="https://github.com/pytorch/pytorch/issues/157788")
    @skipIfRocm(msg="https://github.com/pytorch/pytorch/issues/157724")
    @requires_gpu()
    @requires_triton()
    @unittest.skipIf(
        not IS_BIG_GPU, "Skipping triton backend only since not big GPU (not enough SM)"
    )
    def test_progressive(self):
        # [FUNCTION DOC] Requires a GPU, triton and a big GPU; skipped on ROCm. Turns on
        # progressive FX compilation globally, compiles a bfloat16 matmul plus relu repeatedly
        # with caches disabled and output code capture mocked in, until the optimized run counter
        # reaches 4 (raises RuntimeError after 300 seconds). Then checks fast-run and background
        # start/finish counters, turns progressive mode back off, and unless on XPU asserts via
        # benchmarking that the baseline (non-progressive) compile is slower than the progressive
        # one as measured. Finally checks the last captured source mentions max autotune enabled.
        # KNOWN ISSUE: the benchmark comparison asserts the baseline time is greater than the
        # optimized time, and the global progressive flag is not restored if an earlier assertion
        # fails.
        from triton.testing import do_bench

        from torch._inductor.compile_fx_async import _ProgressiveFxCompile

        torch._inductor.compile_fx.fx_compile_progressive = True

        x = torch.randn(1152, 4096, device=GPU_TYPE, dtype=torch.bfloat16)
        y = torch.randn(4096, 4096, device=GPU_TYPE, dtype=torch.bfloat16)

        @torch.compile(fullgraph=True, backend="inductor")
        def optimized(x, y):
            # [FUNCTION DOC] HELPER: Compiled function: matrix-multiplies the two inputs and
            # applies relu.
            return (x @ y).relu()

        _ProgressiveFxCompile._reset_stats()

        source_codes: list[str] = []

        def save_output_code(code: str) -> None:
            # [FUNCTION DOC] HELPER: Appends the given generated source text to the enclosing list
            # of captured sources; replaces the graph lowering method that saves output code.
            source_codes.append(code)

        with contextlib.ExitStack() as stack:
            # When this bug is fixed, remove the cache disabling below
            if not torch._inductor.compile_fx_async.BUG_CACHES_DONT_WORK_WITH_ASYNC:
                raise AssertionError
            stack.enter_context(
                torch._inductor.config.patch(
                    autotune_local_cache=False, fx_graph_cache=False
                )
            )
            stack.enter_context(
                mock.patch.object(GraphLowering, "save_output_code", save_output_code)
            )
            stack.enter_context(
                torch._functorch.config.patch(enable_autograd_cache=False)
            )

            # How long to wait (in seconds) before giving up.
            TIMEOUT = 300
            # If non-None then how often (in seconds) to print a TICK message.
            TICK_REPORT = None

            start = time.time()
            last_report = start
            while _ProgressiveFxCompile._stat_optimized_runs < 4:
                time.sleep(0.25)

                optimized(x, y)

                now = time.time()
                if TICK_REPORT is not None and (now - last_report > TICK_REPORT):
                    print(f"*** TICK {int(now - start)}")
                    last_report = now

                if now - start > TIMEOUT:
                    raise RuntimeError(
                        "Test timed out before producing a progressively optimized compiled artifact."
                    )

            self.assertEqual(_ProgressiveFxCompile._stat_optimized_runs, 4)
            self.assertGreater(_ProgressiveFxCompile._stat_fast_runs, 0)
            self.assertGreaterEqual(_ProgressiveFxCompile._stat_bg_started, 1)
            self.assertGreaterEqual(_ProgressiveFxCompile._stat_bg_finished, 1)

        torch._inductor.compile_fx.fx_compile_progressive = False

        @torch.compile(fullgraph=True, backend="inductor")
        def baseline(x, y):
            # [FUNCTION DOC] HELPER: Baseline compiled function: matrix-multiplies the two inputs
            # and applies relu.
            return (x @ y).relu()

        # Warmup
        baseline(x, y)

        # Skip the perf assertion to avoid flakiness on XPU.
        if GPU_TYPE != "xpu":
            self.assertGreater(
                do_bench(lambda: baseline(x, y)), do_bench(lambda: optimized(x, y))
            )
        self.assertTrue("'max_autotune': True" in source_codes[-1])

    @patch("torch._inductor.compile_fx.fx_compile_async", True)
    def test_async(self):
        # [FUNCTION DOC] Patches async FX compilation on. Compiles a function that adds a tensor
        # 500 times, with caches disabled, and repeatedly runs forward and backward until exactly
        # two more background compiles complete in one iteration (raising RuntimeError after 300
        # seconds). Then asserts more than one compiled run, at least one eager run while waiting,
        # and exactly two background compiles started and finished.
        # Test that async+subprocess works.
        from torch._inductor.compile_fx_async import _AsyncFxCompile

        @torch.compile(fullgraph=True, backend="inductor")
        def model_add(x, y):
            # [FUNCTION DOC] HELPER: Compiled function: adds the second input to the first 500
            # times in a loop and returns the result.
            out = x
            for _ in range(500):
                out = torch.add(out, y)
            return out

        _AsyncFxCompile._reset_stats()

        with contextlib.ExitStack() as stack:
            if not torch._inductor.compile_fx_async.BUG_CACHES_DONT_WORK_WITH_ASYNC:
                raise AssertionError
            stack.enter_context(
                torch._inductor.config.patch(
                    autotune_local_cache=False, fx_graph_cache=False
                )
            )
            stack.enter_context(
                torch._functorch.config.patch(enable_autograd_cache=False)
            )

            # How long to wait (in seconds) before giving up.
            TIMEOUT = 300
            # If non-None then how often (in seconds) to print a TICK message.
            TICK_REPORT = None

            start = time.time()
            last_report = start
            while True:
                start_stat_compiled_runs = _AsyncFxCompile._stat_compiled_runs
                # Sleep a bit so we don't drive the CPU unnecessarily.
                time.sleep(0.25)

                x = torch.randn(100, 100, requires_grad=True)
                y = torch.randn(100, 100, requires_grad=True)

                # Forward pass
                output = model_add(x, y)

                # Backward pass
                output.sum().backward()

                if _AsyncFxCompile._stat_compiled_runs - start_stat_compiled_runs == 2:
                    break

                # DEBUGGING: Print a periodic message so we know we're still
                # running...
                now = time.time()
                if TICK_REPORT is not None and (now - last_report > TICK_REPORT):
                    print(f"*** TICK {int(now - start)}")
                    last_report = now

                if now - start > TIMEOUT:
                    raise RuntimeError(
                        "Test timed out before producing a compiled artifact."
                    )

            self.assertGreater(_AsyncFxCompile._stat_compiled_runs, 1)
            # Make sure we ran eager at least once. Normally this will be
            # something like 80.
            self.assertGreater(_AsyncFxCompile._stat_eager_runs, 0)
            self.assertEqual(_AsyncFxCompile._stat_bg_started, 2)
            self.assertEqual(_AsyncFxCompile._stat_bg_finished, 2)


